import { useState, type FormEvent } from 'react';
import {
  JxTextField,
  JxSelect,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [successOpen, setSuccessOpen] = useState(false);
  const [sentTo, setSentTo] = useState('');

  const emailTouched = email.length > 0;
  const emailValid = EMAIL_PATTERN.test(email);
  const emailError = emailTouched && !emailValid;
  const canSubmit = emailValid;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canSubmit) return;
    setSentTo(email);
    setSuccessOpen(true);
    setEmail('');
    setRole('member');
    setNotify(true);
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
      <JxAlert
        variant="success"
        open={successOpen}
        onOpenChange={setSuccessOpen}
      >
        Приглашение отправлено на {sentTo}
      </JxAlert>

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}
      >
        <JxTextField
          label="Почта"
          type="email"
          value={email}
          onValueChange={setEmail}
          hint={emailError ? 'Введите корректный email-адрес' : 'Например, name@company.com'}
          error={emailError}
          required
        />

        <JxSelect
          label="Роль"
          value={role}
          onValueChange={setRole}
          options={ROLE_OPTIONS}
        />

        <JxSwitch
          label="Отправить уведомление"
          value={notify}
          onValueChange={setNotify}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

